//! Biosynfoni parity test.
//!
//! Compares FerrumChem's Biosynfoni counts against the original implementation
//! (version `full_1103`, default overlap settings) in
//! `tests/data/biosynfoni_parity_reference.csv`, generated by
//! `scripts/generate_biosynfoni_reference.py`. Baseline and environment
//! variables work as in `rdkit_parity.rs`.

mod common;

#[test]
fn biosynfoni_parity() {
    common::parity::run_parity("Biosynfoni", "biosynfoni_parity_reference.csv", "biosynfoni_parity_baseline.tsv");
}
